def wrap(text, width, indent=""):
    """Wrap `text` to lines of at most `width` characters. See TASK.md."""
    if not isinstance(width, int) or isinstance(width, bool) or width < 1:
        raise ValueError("width must be an int of at least 1")
    if not isinstance(indent, str):
        raise ValueError("indent must be a str")
    if len(indent) >= width:
        raise ValueError("indent must be shorter than width")

    out = []
    for paragraph in text.split("\n"):
        out.extend(_wrap_paragraph(paragraph, width, indent))
    return out


def _wrap_paragraph(paragraph, width, indent):
    words = paragraph.split()
    if not words:
        return [""]

    lines = []  # finished lines of this paragraph (without prefix)

    def prefix():
        # Every line after the first of a paragraph gets the hanging indent.
        return indent if lines else ""

    def avail():
        return width - len(prefix())

    cur = ""
    has_cur = False  # whether `cur` holds any words
    for word in words:
        while True:
            if not has_cur:
                if len(word) <= avail():
                    cur = word
                    has_cur = True
                    break
                # Word does not fit on an empty line: fill the line with as
                # much of it as fits, then continue with the rest.
                room = avail()  # measure before the line is recorded
                lines.append(prefix() + word[:room])
                word = word[room:]
                # `cur` is still empty; loop again with the remainder.
            else:
                if len(cur) + 1 + len(word) <= avail():
                    cur += " " + word
                    break
                # Word does not fit on the current line: finish it, start a new one.
                lines.append(prefix() + cur)
                cur = ""
                has_cur = False

    if has_cur:
        lines.append(prefix() + cur)
    return lines
